{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Increase embedding width from 64 to 128 across all four datasets to test greater representational capacity. Existing width-dependent encoder layers, checkpoint metadata, and predictor construction automatically propagate the new width. Preserve two blocks, two heads, tied embeddings, initialization, scoring, masked training, loss, and optimizer.",
      "edits": [
        {
          "find": "HIDDEN_UNITS  = int(os.environ.get(\"BERT4REC_HIDDEN\", \"64\"))",
          "replace": "HIDDEN_UNITS  = int(os.environ.get(\"BERT4REC_HIDDEN\", \"128\"))"
        },
        {
          "find": "    def __init__(self, itemnum: int, hidden_units: int = 64, num_blocks: int = 2,",
          "replace": "    def __init__(self, itemnum: int, hidden_units: int = 128, num_blocks: int = 2,"
        }
      ]
    }
  ],
  "change_summary": "Double BERT4Rec embedding width to 128 for all four category models. Existing metadata and embedded predictor writer retain checkpoint shape consistency."
}
